using System.Globalization;
using System.Xml.Linq;
namespace SvgMusic.Scene;
public sealed class DebugSceneRenderer
{
 private static readonly string[] Palette=["#e6194b","#3cb44b","#4363d8","#f58231","#911eb4","#008b8b","#f032e6","#6b8e23","#c71585","#008080","#7b68ee","#9a6324","#b8860b","#800000","#2e8b57","#808000","#d2691e","#000075"];
 public void RenderAll(string input,NotationScene scene,string dir,string name){Render(input,Path.Combine(dir,name+".strokes.svg"),(r,n)=>AddStrokes(r,n,scene));Render(input,Path.Combine(dir,name+".arcs.svg"),(r,n)=>AddCurves(r,n,scene));Render(input,Path.Combine(dir,name+".ellipses.svg"),(r,n)=>AddEllipses(r,n,scene));Render(input,Path.Combine(dir,name+".contours.svg"),(r,n)=>AddContours(r,n,scene));}
 private static void Render(string input,string output,Action<XElement,XNamespace> add){var d=XDocument.Load(input,LoadOptions.PreserveWhitespace);var r=d.Root??throw new InvalidOperationException("SVG has no root element.");add(r,r.Name.Namespace);d.Save(output,SaveOptions.DisableFormatting);}
 private static void AddStrokes(XElement r,XNamespace n,NotationScene s){var g=Group(n,"debug-strokes");foreach(var x in s.Strokes)g.Add(new XElement(n+"line",new XAttribute("x1",F(x.Start.X)),new XAttribute("y1",F(x.Start.Y)),new XAttribute("x2",F(x.End.X)),new XAttribute("y2",F(x.End.Y)),new XAttribute("stroke","#00a7d6"),new XAttribute("stroke-width",F(Math.Clamp(x.Width+3,4,12))),new XAttribute("stroke-linecap","round"),new XAttribute("opacity","0.75")));r.Add(g);}
 private static void AddCurves(XElement r,XNamespace n,NotationScene s){var g=Group(n,"debug-curved-strokes");foreach(var c in s.CurvedStrokes){if(c.Centerline.Count<2)continue;var d="M "+F(c.Centerline[0].X)+" "+F(c.Centerline[0].Y)+string.Concat(c.Centerline.Skip(1).Select(p=>$" L {F(p.X)} {F(p.Y)}"));g.Add(new XElement(n+"path",new XAttribute("d",d),new XAttribute("fill","none"),new XAttribute("stroke","#d81b60"),new XAttribute("stroke-width","5"),new XAttribute("stroke-linecap","round"),new XAttribute("stroke-linejoin","round"),new XAttribute("opacity","0.82")));}r.Add(g);}
 private static void AddEllipses(XElement r,XNamespace n,NotationScene s){var g=Group(n,"debug-ellipses");foreach(var e in s.Ellipses){var degrees=e.Rotation*180/Math.PI;g.Add(new XElement(n+"ellipse",new XAttribute("cx",F(e.Center.X)),new XAttribute("cy",F(e.Center.Y)),new XAttribute("rx",F(e.MajorRadius)),new XAttribute("ry",F(e.MinorRadius)),new XAttribute("transform",$"rotate({F(degrees)} {F(e.Center.X)} {F(e.Center.Y)})"),new XAttribute("fill",e.IsHollow?"none":"#20a050"),new XAttribute("fill-opacity",e.IsHollow?"0":"0.25"),new XAttribute("stroke",e.IsHollow?"#7b1fa2":"#20a050"),new XAttribute("stroke-width","4"),new XAttribute("opacity","0.9")));}r.Add(g);}
 private static void AddContours(XElement r,XNamespace n,NotationScene s){var g=Group(n,"debug-contours");foreach(var i in s.Instances){var x=ParsePrototypeIndex(i.PrototypeId);var c=Palette[(x-1)%Palette.Length];var fs=Math.Clamp(Math.Max(i.Width,i.Height)*.28,14,28);g.Add(new XElement(n+"rect",new XAttribute("x",F(i.X)),new XAttribute("y",F(i.Y)),new XAttribute("width",F(i.Width)),new XAttribute("height",F(i.Height)),new XAttribute("fill","none"),new XAttribute("stroke",c),new XAttribute("stroke-width","3")),new XElement(n+"text",new XAttribute("x",F(i.X)),new XAttribute("y",F(Math.Max(fs,i.Y-4))),new XAttribute("font-family","Arial, sans-serif"),new XAttribute("font-size",F(fs)),new XAttribute("font-weight","700"),new XAttribute("fill",c),new XAttribute("stroke","white"),new XAttribute("stroke-width","2"),new XAttribute("paint-order","stroke fill"),$"p{x}"));}r.Add(g);}
 private static XElement Group(XNamespace n,string id)=>new(n+"g",new XAttribute("id",id),new XAttribute("pointer-events","none"));private static int ParsePrototypeIndex(string id){var d=id.LastIndexOf('-');return d>=0&&int.TryParse(id[(d+1)..],out var v)?Math.Max(1,v):1;}private static string F(double v)=>v.ToString("0.###",CultureInfo.InvariantCulture);
}
